import { createFileRoute } from '@tanstack/react-router'
export const Route = createFileRoute('/dashboard/invoices/$invoiceId')({
  params: { parse: (p) => ({ invoiceId: Number(p.invoiceId) }) },
  component: InvoiceComponent,
})

export const Route = createFileRoute('/login')({
  validateSearch: z.object({ redirect: z.string().optional() }),
}).update({
  component: LoginComponent,
})

import { createRootRoute, createRoute } from '@tanstack/react-router'
const rootRoute = createRootRoute({ component: RootComponent })
const indexRoute = createRoute({
  getParentRoute: () => rootRoute,
  path: '/',
  component: IndexComponent,
})
const postsLayoutRoute = createRoute({
  getParentRoute: () => rootRoute,
  path: 'posts',
  component: PostsLayoutComponent,
})
const postsIndexRoute = createRoute({
  getParentRoute: () => postsLayoutRoute,
  path: '/',
  component: PostsIndexComponent,
})
const postRoute = createRoute({
  getParentRoute: () => postsLayoutRoute,
  path: '$postId',
  component: PostComponent,
})
const pathlessRoute = createRoute({
  getParentRoute: () => rootRoute,
  id: 'pathless',
  component: PathlessComponent,
})
const routeARoute = createRoute({
  getParentRoute: () => pathlessRoute,
  path: '/route-a',
  component: RouteAComponent,
})

